#include "hangar/UniversalDockedStationSystem.h"
#include <algorithm>
namespace subspace {
namespace { bool Has(const GeneratedStationProfile&s,const char* token){return std::any_of(s.services.begin(),s.services.end(),[&](const std::string&v){return v.find(token)!=std::string::npos;});} }
DockedStationPresentation UniversalDockedStationSystem::Build(const GeneratedStationProfile&s) const {DockedStationPresentation p;p.type=s.archetype;p.services=s.services;switch(s.archetype){case StationArchetype::IndustrialRefinery:case StationArchetype::MiningDepot:p.hangarProfile="INDUSTRIAL_BERTH";break;case StationArchetype::Military:p.hangarProfile="ARMORED_CLAMP";break;case StationArchetype::Shipyard:p.hangarProfile="SHIPYARD_FRAME";break;case StationArchetype::TetherTerminal:p.hangarProfile="PLANETARY_TETHER_ORBIT";break;case StationArchetype::AsteroidStation:p.hangarProfile="EXCAVATED_ASTEROID_BERTH";break;case StationArchetype::Research:p.hangarProfile="RESEARCH_SPINDLE";break;default:p.hangarProfile="TRADE_HANGAR";break;}
    p.serviceProfile.refuel=Has(s,"Fuel")||Has(s,"Refuel");p.serviceProfile.repairHull=Has(s,"Repair");p.serviceProfile.repairModules=p.serviceProfile.repairHull;p.serviceProfile.refit=Has(s,"Fitting")||Has(s,"Shipyard");p.serviceProfile.storage=Has(s,"Storage")||Has(s,"Cargo");p.serviceProfile.market=Has(s,"Market");p.serviceProfile.shipyard=Has(s,"Shipyard");
    const StationServiceType all[]={StationServiceType::Refuel,StationServiceType::RepairHull,StationServiceType::RepairModules,StationServiceType::Refit,StationServiceType::Storage,StationServiceType::Market,StationServiceType::Shipyard};StationServiceSystem service;for(auto t:all)if(service.IsAvailable(p.serviceProfile,t,0.0))p.availableServiceTypes.push_back(t);return p;}
}
